// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/bots", wrapper.ListBots)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/chatbot/bots", wrapper.CreateBot)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/chatbot/bots/{id}", wrapper.DeleteBot)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/bots/{id}", wrapper.GetBot)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/chatbot/bots/{id}", wrapper.UpdateBot)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/bots/{id}/knowledge", wrapper.ListKnowledge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/chatbot/bots/{id}/knowledge", wrapper.AddKnowledge)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/chatbot/knowledge/{id}", wrapper.DeleteKnowledge)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/bots/{id}/questions", wrapper.ListQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/chatbot/bots/{id}/questions", wrapper.SetQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/conversations", wrapper.ListConversations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/conversations/{id}", wrapper.GetConversation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/chatbot/conversations/{id}/reply", wrapper.ReplyToConversation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/chatbot/conversations/{id}/close", wrapper.CloseConversation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/chatbot/handoffs", wrapper.ListHandoffs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/public/chat/{key}/config", wrapper.GetChatConfig)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/public/chat/{key}/conversations", wrapper.StartChat)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/public/chat/{key}/messages", wrapper.SendChatMessage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/public/chat/{key}/poll", wrapper.PollChat)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/public/chat/{key}/lead", wrapper.CaptureChatLead)
	})

	return r
}

